// ONE definition of "what the persistent Console runtime is" and "which generation is running".
//
// #79 reported a Console that survived an update: the browser was served the new frontend from disk
// while the Node process kept its pre-update router in memory, and every relaunch said "already
// running". The reuse check compared a `sourceSha256` computed from a SINGLE file —
// scripts/onboarding-console.mjs — while the runtime the server actually executes is this whole
// surface: ~230 modules it imports plus the frontend it serves. Two genuinely different candidates
// whose entrypoint bytes happened to match produced byte-identical identities, so an update that
// changed console-engine.mjs, capability-registry.mjs or console/app.js was invisible to the
// launcher. The identity has to derive from something an update cannot leave behind, which is the
// installed bytes themselves — all of them.
//
// #76 reported the same disease at the asset boundary: the runtime copied plugin/scripts without
// the sibling docs/ and manifest that plugin/scripts/whats-new.mjs reads, so the executable
// travelled and its assets did not. The copy list and the identity list were two separate
// enumerations of one payload; they are one list now, so an asset added to the runtime is part of
// its generation by construction.
//
// The installer hashes the staged tree with this function and the running server hashes its own
// root with this function, over this list. Neither side can define the fact differently.

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

/**
 * Every path the persistent Console runtime carries, relative to both the candidate source root and
 * the installed runtime root (they are laid out identically). This is simultaneously the installer's
 * copy list and the generation's digest input — one enumeration, so they cannot drift.
 */
export const CONSOLE_RUNTIME_SURFACE = Object.freeze([
  'console',
  'scripts',
  'plugin/scripts',
  // whats-new.mjs resolves its version manifest and curated notes relative to its own plugin root
  // (#76). Shipping the executable without them is how the installed skill lost its release notes.
  'plugin/docs',
  'plugin/.claude-plugin',
  'data/model-catalog.json',
  'kb/brain-profile.mjs',
  // The staged installer imports these helpers, including ZIP extraction on its update path.
  // Keep their bytes in the same copy/digest authority as the installer itself.
  'kb/refresh-run.mjs',
  'kb/lifecycle-evidence-retention.mjs',
  // install.mjs --update recovers an interrupted storage transaction before it looks for the updater.
  'kb/update-storage-transaction.mjs',
  'kb/model-requirements.mjs',
  'kb/zip-extract.mjs',
  'kb/download-retry.mjs',
  // install.mjs imports this STATICALLY (corpus transport identity + approved-runtime stamping,
  // ADR-086 step 16). A copied installer whose sibling is missing does not degrade — it throws
  // ERR_MODULE_NOT_FOUND on import, before a single line runs.
  'kb/corpus-release-identity.mjs',
  'bin/install.mjs',
  // The Console's Settings → Nightly switch runs the copied installer's --enable-nightly, which installs
  // THIS file (beside it, REPO_ROOT/bin) as the scheduler's immutable runner. Without it every installed
  // customer got "nightly runner source is missing" (RNBC review 2026-10-01). It imports only node:
  // built-ins, so nothing further travels with it.
  'bin/nightly-refresh.mjs',
  'bin/developer-update.mjs',
  'package.json',
]);

/** The runtime's own identity file, written by the installer INTO the tree — never part of its own digest. */
export const CONSOLE_RUNTIME_IDENTITY_FILE = 'runtime-identity.json';

/**
 * Deterministic content digest of the runtime surface under `root`.
 *
 * A path that is absent is hashed as absent rather than skipped: a runtime that lost a file is a
 * different generation, not the same one, and a launcher must be able to see that.
 *
 * @param {string} root runtime root (an installed `.console-runtime`, a marketplace clone, or a checkout)
 * @returns {string} hex sha256
 */
export function consoleRuntimeDigest(root) {
  const hash = crypto.createHash('sha256');
  const visit = (absolute, relative) => {
    let stat;
    try { stat = fs.lstatSync(absolute); } catch { hash.update(`absent\0${relative}\0`); return; }
    if (stat.isDirectory()) {
      hash.update(`d\0${relative}\0`);
      let entries = [];
      try { entries = fs.readdirSync(absolute).sort(); } catch { hash.update(`unreadable\0${relative}\0`); return; }
      for (const entry of entries) visit(path.join(absolute, entry), `${relative}/${entry}`);
      return;
    }
    hash.update(`f\0${relative}\0`);
    try { hash.update(fs.readFileSync(absolute)); } catch { hash.update(`unreadable\0${relative}\0`); }
  };
  for (const relative of CONSOLE_RUNTIME_SURFACE) visit(path.join(root, relative), relative);
  return hash.digest('hex');
}

#!/usr/bin/env node
// Fixture-generation adapter used only by scripts/learning-replay.mjs.
// The installed Codex plugin manifest calls the stable user-level wrapper. RUVNET_BRAIN_HOME makes
// that wrapper resolve this isolated generation, where this adapter observes the real lesson hook
// and blocks the first command before the model can learn the CLI syntax from its output.

import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const raw = fs.readFileSync(0);
let input = {};
try { input = JSON.parse(raw.toString('utf8')); } catch { /* fail closed below for tool calls */ }

const hookId = process.argv[2] || '';
const event = String(input.hook_event_name || '');
const here = path.dirname(fileURLToPath(import.meta.url));
const sequenceFile = process.env.RUVNET_REPLAY_SEQUENCE_FILE || '';
const attemptsFile = process.env.RUVNET_REPLAY_ATTEMPTS_FILE || '';
const probe = process.env.RUVNET_REPLAY_LESSON_PROBE || '';

if (event === 'PreToolUse') {
  const recorder = process.env.RUVNET_REPLAY_RECORDER || '';
  if (!recorder) process.exit(2);
  // Codex emits exec_command with tool_input.cmd; the shared Claude/Ruflo boundary consumes
  // Bash with tool_input.command. Normalize the real host envelope before the recorder parses it.
  const recorderInput = Buffer.from(JSON.stringify({
    ...input,
    tool_name: /^(?:functions[._]{1,2})?exec_command$/.test(String(input.tool_name || ''))
      ? 'Bash'
      : input.tool_name,
    tool_input: {
      ...(input.tool_input || {}),
      command: input.tool_input?.command ?? input.tool_input?.cmd ?? input.command ?? '',
    },
  }));
  const result = spawnSync(process.execPath, [recorder, attemptsFile, sequenceFile], {
    input: recorderInput,
    encoding: 'utf8',
    env: process.env,
  });
  if (result.stdout) process.stdout.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  process.exit(result.status ?? 2);
}

if (event === 'UserPromptSubmit' && hookId === 'unprompted-speech') {
  const shim = path.join(here, 'hook-shim.mjs');
  const result = spawnSync(process.execPath, [shim, hookId, ...process.argv.slice(3)], {
    input: raw,
    encoding: 'utf8',
    env: {
      ...process.env,
      CLAUDE_SESSION_ID: String(input.session_id || ''),
      CLAUDE_PROJECT_DIR: String(input.cwd || process.cwd()),
      RUVNET_HOOK_HOST: 'codex',
    },
  });
  if (probe && String(result.stdout || '').includes(probe) && sequenceFile) {
    try {
      fs.mkdirSync(path.dirname(sequenceFile), { recursive: true });
      fs.appendFileSync(sequenceFile, JSON.stringify({
        kind: 'lesson',
        atNs: process.hrtime.bigint().toString(),
      }) + '\n');
    } catch { /* a missing receipt makes the replay fail closed */ }
  }
  if (result.stdout) process.stdout.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  process.exit(result.status ?? 0);
}

process.exit(0);
